import { clone, validateSurfaceTemplate, defaultGeology } from './planetary-surface-model.js';
import { resourceRandom } from './ore-quality.js';
import { generateBodyResources } from './body-resource-generator.js';
import { allocateInteger, resourceQuanta } from './planetary-data-generator.js';
import { summarizeOre, oreDeposits } from './resource-contract.js';
export function migrateSurfaceV1(template,grid,body){validateSurfaceTemplate(template,grid,body);const next=clone(template);if(next.schemaVersion===2)return next;next.schemaVersion=2;next.resourceConfiguration=null;next.hydrogenSources=[];next.initialResourceKnowledge=[];next.migration={migrationVersion:1,fromSchemaVersion:1,notes:'명시적 v1→v2. 기존 광석을 표면형·품질60/38/2의 미검증 레거시 가정으로 이관. 원본/시나리오/ID/총량 보존.'};for(const g of Object.values(next.geology.cells))for(const d of g.deposits??[])if(d.resourceId==='ore')Object.assign(d,{depositKind:'surface',groupId:'legacy-'+d.depositId.slice(0,60)+'-'+Math.floor(resourceRandom(d.depositId)*2**32).toString(16),gradeProbabilities:{low:.6,medium:.38,high:.02},processingDifficulty:30,accessDepth:0,compositionTags:[]});validateSurfaceTemplate(next,grid,body);return next;}
export function planBodyResourceGeneration({template,grid,body,worldSeed,policy='fixedBudget',settings,writePolicy='fill-unset',selectedIds=null,knowledgePolicy='preserve'}){
 validateSurfaceTemplate(template,grid,body);if(!['fill-unset','overwrite'].includes(writePolicy))throw Error('쓰기 정책 오류');const next=migrateSurfaceV1(template,grid,body),eligible=(selectedIds??grid.tiles.map(t=>t.id)).filter(id=>{if(!grid.byId.has(id))throw Error('다른 표면 구역 ID');return writePolicy==='overwrite'||(next.geology.cells[id]?.deposits??null)===null;}),eligibleSet=new Set(eligible),fixed=oreDeposits(next).filter(d=>!eligibleSet.has(d.tileId));
 const landFractionsByTile=Object.fromEntries(grid.tiles.map(t=>[t.id,next.geology.cells[t.id]?.terrain.landFraction??null]));
 const full=generateBodyResources({systemId:grid.systemId,body,grid,worldSeed,policy,settings,landFractionsByTile}),cfg=clone(full.configuration);if(cfg===null)return {nextTemplate:next,baseJSON:JSON.stringify(template),before:summarizeOre(next),after:summarizeOre(next),changedCells:0,protectedCells:grid.cellCount-eligible.length};
 const budgets=Object.fromEntries(allocateInteger(resourceQuanta(cfg.totalOreU),Object.entries(cfg.typeShares).map(([id,weight])=>({id,weight})))),targets=clone(cfg.gradeTargets),remainders={};
 for(const kind of ['surface','vein','deep']){const preserved=fixed.filter(d=>d.depositKind===kind),reserved=preserved.reduce((n,d)=>n+resourceQuanta(d.initialReserveU),0),remaining=budgets[kind]-reserved;remainders[kind]=remaining;if(remaining<0)throw Error('보호할 '+kind+' 매장량이 전체 목표를 초과합니다.');if(remaining>0){for(const k of ['low','medium','high'])targets[kind][k]=(budgets[kind]*cfg.gradeTargets[kind][k]-preserved.reduce((n,d)=>n+resourceQuanta(d.initialReserveU)*d.gradeProbabilities[k],0))/remaining;}else if(preserved.length)for(const k of ['low','medium','high'])if(Math.abs(preserved.reduce((n,d)=>n+resourceQuanta(d.initialReserveU)*d.gradeProbabilities[k],0)/reserved-cfg.gradeTargets[kind][k])>1e-6)throw Error('보호된 매장지와 품질 평균 타깃이 모순됩니다.');}
 const generated=generateBodyResources({systemId:grid.systemId,body,grid,worldSeed,policy:'fixedBudget',settings:{...cfg,gradeTargets:targets},tileIds:eligible,budgetsByKind:remainders,landFractionsByTile});
 for(const id of eligible){next.geology.cells[id]??=defaultGeology(body);const others=(next.geology.cells[id].deposits??[]).filter(d=>d.resourceId!=='ore');next.geology.cells[id].deposits=[...others,...generated.cells[id]];}
 next.resourceConfiguration=cfg;if(next.migration)next.migration.notes='v1→v2 구조 이관. 이후 명시적 자원 재구성은 resourceConfiguration/실제 deposits에 기록, 초기 지형/시나리오 보존.';if(writePolicy==='overwrite'&&eligible.length===grid.cellCount)next.hydrogenSources=generated.hydrogenSources;else if(!next.hydrogenSources.length)next.hydrogenSources=generated.hydrogenSources;
 let droppedKnowledge=0;if(knowledgePolicy==='remap'){const oldById=new Map(oreDeposits(migrateSurfaceV1(template,grid,body)).map(d=>[d.depositId,d])),bySlot=new Map(oreDeposits(next).map(d=>[d.tileId+'/'+d.depositKind,d]));next.initialResourceKnowledge=next.initialResourceKnowledge.map(c=>({...c,deposits:c.deposits.flatMap(k=>{const old=oldById.get(k.depositId),d=old&&bySlot.get(old.tileId+'/'+old.depositKind);if(!d){droppedKnowledge++;return [];}return [{...k,depositId:d.depositId}];})}));}else if(knowledgePolicy!=='preserve')throw Error('인지 이관 정책 오류');
 // Old cell-level and tier-specific references are validated rather than silently completing surveys.
 validateSurfaceTemplate(next,grid,body);const changedCells=grid.tiles.filter(t=>JSON.stringify(next.geology.cells[t.id]?.deposits)!==JSON.stringify(template.geology.cells[t.id]?.deposits)).length;
 return {nextTemplate:next,baseJSON:JSON.stringify(template),before:summarizeOre(template.schemaVersion===2?template:migrateSurfaceV1(template,grid,body)),after:summarizeOre(next),changedCells,protectedCells:grid.cellCount-eligible.length,droppedKnowledge};
}
